"""Finite observation fiber screen; initial checker frozen before fixtures."""
from dataclasses import dataclass
from collections import defaultdict

@dataclass(frozen=True)
class Trace:
    # Identity of one installed law, distinct from an execution's event ID.
    installation: tuple
    event: tuple
    # Explicit qualified positive, explicit qualified negative, or missing.
    report: str
    # Each actual source effect (not generated by the monitor).
    paid: tuple

def candidates(rows, admitted, report):
    return tuple(r for r in rows if r.installation in admitted and r.report==report)

def projection_then_expand(rows, admitted, report):
    admitted_history=candidates(rows, admitted, report)
    kept={r.installation for r in admitted_history}
    return tuple(r for r in rows if r.installation in kept)

def verdict(rows,index):
    answers={r.paid[index] for r in rows}
    if not answers:
        return 'inconsistent'
    if answers=={True}:
        return 'safe'
    if answers=={False}:
        return 'all-bad'
    return 'mixed'

def support_index(rows,index):
    """Saturation permits portable lookup, but do not assume it for each law."""
    by_law=defaultdict(set)
    by_observation=defaultdict(set)
    for r in rows:
        by_law[r.installation].add(r.paid[index])
        by_observation[r.installation,r.report].add(r.paid[index])
    return by_law,by_observation
